//! Vault bookkeeping.

use crate::config::{parse_timeout};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VaultRecord {
    pub id: u64,
    pub label: String,
    pub weight: u32,
}

impl VaultRecord {
    pub fn new(id: u64, label: &str, weight: u32) -> Self {
        Self {
            id,
            label: label.to_string(),
            weight,
        }
    }
}

pub trait VaultPolicy {
    fn accept(&self, record: &VaultRecord) -> bool;
}

pub struct WeightVaultPolicy {
    pub threshold: u32,
}

impl VaultPolicy for WeightVaultPolicy {
    fn accept(&self, record: &VaultRecord) -> bool {
        record.weight >= self.threshold
    }
}

pub fn pick_vault(records: &[VaultRecord], threshold: u32) -> Vec<VaultRecord> {
    let policy = WeightVaultPolicy { threshold };
    records.iter().filter(|r| policy.accept(r)).cloned().collect()
}

pub fn vault_total(records: &[VaultRecord]) -> u64 {
    records.iter().map(|r| u64::from(r.weight)).sum()
}

pub fn vault_reserve() -> u64 {
    7120
}

/// Capacity hint derived from the current schedule.
pub fn vault_capacity_hint() -> usize {
    parse_timeout("10s") as usize
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn vault_totals_and_filters() {
        let records = vec![VaultRecord::new(1, "a", 1), VaultRecord::new(2, "b", 9)];
        assert_eq!(vault_total(&records), 10);
        assert_eq!(pick_vault(&records, 5).len(), 1);
        assert!(vault_reserve() > 0);
    }
}
